//go:build amd64

package floats

import "unsafe"

// The AVX2+FMA kernel of CMulTo (cmulto.go), generated by go-asmgen (cmulto_amd64_gen.go)
// into cmulto_amd64.s: steps of four complex numbers (a complex128 is two adjacent
// float64, which the kernel reads as such), then a step of two and one of one, all in
// one call, for a CPU with the AVX2+FMA of the other kernels (hasAVX2FMA); the portable
// loop otherwise. Pointers and a count, as the call is short at the sizes of a small
// transform: no Go tail follows it (go-simd/floats#82). go:noescape.
//
//go:noescape
func cmulToAVX2(dst, a, b *float64, n int)

func cmulTo(dst, a, b []complex128) {
	if len(dst) > 0 && hasAVX2FMA {
		cmulToAVX2(f64ptr(&dst[0]), f64ptr(&a[0]), f64ptr(&b[0]), len(dst))
		return
	}
	cmulToTail(dst, a, b, 0)
}

func f64ptr(p *complex128) *float64 { return (*float64)(unsafe.Pointer(p)) }
